import json, re, unicodedata
SP = r"C:\wt\logos-t423-m8-fable\.ai\scratch\multi_model_bible_chunking\M8_fable\sp_durable"
inv = json.load(open(SP + r"\Dan\dan_device_inventory.json", encoding="utf-8"))
F = inv["formulae"]
O = dict(l.split("\t", 1) for l in open(SP + r"\Dan\Dan_oshb.txt", encoding="utf-8").read().split("\n") if "\t" in l)
def sk(s): return "".join(c for c in unicodedata.normalize("NFD", s) if not 0x591 <= ord(c) <= 0x5C7)
d = F["at_that_moment_aram"]
alts = d["pattern"].split("|")
print("alternatives in the pattern:", len(alts), "verses_mt:", len(d["verses_mt"]))
for v in d["verses_mt"]:
    w = [sk(x) for x in O[v].split(" ")]
    for i, a in enumerate(alts):
        for j in range(len(w) - 1):
            if re.fullmatch(a, w[j] + " " + w[j + 1]): print(v, "alternative", i + 1, "at words", j + 1, "and", j + 2, "of", len(w))
